  "headline": "Vincristine sulfate is not on FDA's shortage list; our supply traces to a plant with a 2014 OAI inspection and Warning Letter",
  "headline_cites": ["D3", "E5", "E7"],
  "sentences": [
    {
      "text": "As of 2026-10-21, vincristine sulfate is not on FDA's drug shortage list.",
      "cites": ["D3"]
    },
    {
      "text": "The product label identifies Hospira Australia Pty Ltd (FEI 3001174929) as the manufacturing plant.",
      "cites": ["E8"]
    },
    {
      "text": "FDA inspection 869582 at that plant ended 2014-03-04 and was classified OAI.",
      "cites": ["E5"]
    },
    {
      "text": "A Warning Letter was issued to the plant on 2014-09-26.",
      "cites": ["E7"]
    },
    {
      "text": "The most recent inspection 1181593 ended 2022-09-02 and was classified VAI.",
      "cites": ["E6"]
    },
    {
      "text": "Corvale East has 20.4 days on hand and Corvale General has 23.3 days on hand at current use.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "Check whether the 2014 OAI and Warning Letter history has been fully resolved and monitor the plant's inspection status for any new actions.",
      "cites": ["E5", "E7", "E6"]
    }
  ]
}
